"""Authored SQL and relational-database lessons for placement preparation."""
from __future__ import annotations


def _section(heading, body, code, pro_tip=""):
    item = {"heading": heading, "body": body, "code": code}
    if pro_tip:
        item["pro_tip"] = pro_tip
    return item


def _quiz(question, options, answer, explanation):
    return {"question": question, "options": options, "answer": answer, "explanation": explanation}


def _exercise(title, task, starter, solution, hint=""):
    item = {"title": title, "task": task, "starter": starter, "solution": solution}
    if hint:
        item["hint"] = hint
    return item


def _article(article_id, title, summary, level, related, sections, takeaways, quiz, exercise, read_time=12):
    return {
        "id": article_id,
        "title": title,
        "category": "sql",
        "summary": summary,
        "level": level,
        "read_time_min": read_time,
        "related_topics": related,
        "sections": sections,
        "key_takeaways": takeaways,
        "tag": "Placement core",
        "quiz": quiz,
        "exercise": exercise,
        "curriculum": ["sql"],
    }


